"""Keyword-based live suggestions; no fabricated YouTube trend ranking."""
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime, timezone
import json
from pathlib import Path
import re
import threading
from urllib.parse import urlencode
import xml.etree.ElementTree as ET

_WRITE_LOCK = threading.RLock()


def clean_tag(text):
    return re.sub(r"[^\w]", "", str(text or ""), flags=re.UNICODE)[:60]


def parse_tags(text):
    values = text if isinstance(text, (list, tuple)) else re.split(r"[,\n]+", str(text or ""))
    out, seen = [], set()
    for value in values:
        candidates = re.findall(r"#([^\s,#]+)", str(value)) if "#" in str(value) else [value]
        for item in candidates:
            tag = clean_tag(item)
            if tag and tag.casefold() not in seen:
                out.append(tag)
                seen.add(tag.casefold())
    return out[:15]


def description_with_tags(description, tags):
    # Replace the generated hashtag line when a keyword override is explicitly applied.
    description = re.sub(r"(?<!\w)#[\w-]+", "", str(description or ""))
    description = "\n".join(line.rstrip() for line in description.splitlines()).strip()
    suffix = " ".join('#' + tag for tag in parse_tags(tags)[:5])
    return (description[:max(0, 4998-len(suffix))].rstrip() + '\n\n' + suffix).strip()


def research(keyword, country="PK", get=None):
    keyword = ' '.join(str(keyword or '').split())[:80]
    if not keyword:
        raise ValueError('Enter a topic such as Minecraft or GTA 6 first.')
    country = country if country in ('PK', 'US', 'GB', 'IN') else 'PK'
    if get is None:
        import requests
        get = requests.get
    base = clean_tag(keyword)
    suggestions, trends, problems = [], [], []
    suggestion_url = 'https://suggestqueries.google.com/complete/search'
    trend_url = 'https://trends.google.com/trending/rss?geo=' + country

    def suggestions_request():
        response = get(suggestion_url, params={'client':'firefox', 'ds':'yt', 'q':keyword, 'hl':'en', 'gl':country}, timeout=10)
        response.raise_for_status()
        data = response.json()
        return data[1] if isinstance(data, list) and len(data) > 1 and isinstance(data[1], list) else []

    def trends_request():
        response = get(trend_url, timeout=10)
        response.raise_for_status()
        return [node.findtext('title', '') for node in ET.fromstring(response.text[:1_000_000]).findall('.//item')]

    with ThreadPoolExecutor(max_workers=2) as pool:
        pending = [(pool.submit(suggestions_request), 'suggestions'), (pool.submit(trends_request), 'trends')]
        for future, kind in pending:
            try:
                values = future.result()
                relevant = [str(item) for item in values if base.casefold() in clean_tag(item).casefold()]
                if kind == 'suggestions':
                    suggestions = relevant[:10]
                else:
                    trends = relevant[:5]
            except Exception:
                problems.append(kind)
    tags = parse_tags([keyword] + trends + suggestions)[:10]
    stamp = datetime.now(timezone.utc).strftime('%Y-%m-%d %H:%M UTC')
    note = f'**Topic:** {keyword} · **Checked:** {stamp}\n\n'
    if suggestions:
        note += '**Live YouTube search suggestions:** ' + '; '.join(suggestions) + '\n\n'
    else:
        note += 'No live YouTube suggestions were available. The base keyword below is a manual suggestion.\n\n'
    if trends:
        note += '**Matching Google Search trending topics:** ' + '; '.join(trends) + '\n\n'
    else:
        note += 'No matching topic found in today’s Google Trends feed. These tags are not verified trending YouTube hashtags.\n\n'
    if problems:
        note += 'Unavailable sources: ' + ', '.join(problems) + '.\n\n'
    note += 'Choose only tags that describe your actual video. No search-volume or ranking claim. Only your keyword is sent online.\n\n'
    note += '[YouTube search suggestions](' + suggestion_url + '?' + urlencode({'client':'firefox','ds':'yt','q':keyword}) + ') · [Google Trends RSS](' + trend_url + ')'
    return ', '.join(tags), note


def save_video_tags(path, tags, keyword='', root=None, description=None, title=None):
    path = Path(path).resolve()
    if root is not None and not path.is_relative_to((Path(root) / 'sessions').resolve()):
        raise ValueError('Choose a finished video from this app.')
    if not path.is_file():
        raise ValueError('The video is no longer present.')
    values = parse_tags(tags)
    if not values:
        raise ValueError('Research or enter hashtags first.')
    with _WRITE_LOCK:
        meta = path.parent / 'metadata.json'
        try:
            items = json.loads(meta.read_text(encoding='utf-8-sig'))
        except (OSError, ValueError):
            items = []
        if not isinstance(items, list):
            items = []
        item = next((it for it in items if Path(str(it.get('file',''))).name == path.name), None)
        if item is None:
            item = {'file':path.name, 'title':path.stem.replace('_',' '), 'description':''}
            items.append(item)
        if description is not None:
            item['description'] = str(description)
        if title is not None:
            item['title'] = str(title)
        item.update(tags=values, description=description_with_tags(item.get('description',''), values), hashtag_keyword=keyword)
        _atomic_json(meta, items)
        results = path.parent / 'results.json'
        try:
            data = json.loads(results.read_text(encoding='utf-8-sig'))
            for clip in data.get('clips', []):
                if Path(str(clip.get('video_path','')).replace('\\','/')).name == path.name:
                    clip.update(tags=values, description=item['description'])
            _atomic_json(results, data)
        except (OSError, ValueError, AttributeError):
            pass
        if root is not None and (Path(root)/'schedule.json').is_file():
            from shortsflow import schedule
            with schedule.LOCK:
                jobs = schedule._load(str(root))
                changed = False
                for job in jobs:
                    if job.get('status') == 'pending' and Path(job.get('path','')).resolve() == path:
                        job['tags'] = ', '.join(values)
                        job['description'] = description_with_tags(job.get('description',''),values)
                        changed = True
                if changed:
                    schedule._save(str(root),jobs)
        return item['description'], ', '.join(values)


def _atomic_json(path, data):
    pending = path.with_name(path.name + '.hashtag-tmp')
    pending.write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    pending.replace(path)


def apply_to_cards(cards, keyword, tags, root):
    out = []
    for card in cards or []:
        card = dict(card)
        path = card.get('video') or card.get('path')
        if path:
            desc, values = save_video_tags(path, tags, keyword, root, card.get('description'), card.get('title'))
            card.update(description=desc, tags=parse_tags(values))
        out.append(card)
    return out
